<form class="card-s mb-3 row g-2 align-items-end" method="get"><div class="col-6 col-md-3"><label class="form-label" for="from">من</label><input class="form-control" type="date" id="from" name="from" value="<?= e($from) ?>"></div><div class="col-6 col-md-3"><label class="form-label" for="to">إلى</label><input class="form-control" type="date" id="to" name="to" value="<?= e($to) ?>"></div>
  <div class="col-12 col-md-6 d-flex gap-2"><button class="btn btn-primary" type="submit">عرض</button><?php if (can('reports.export')): ?><a class="btn btn-outline-success" href="<?= url('school/fees/collections.xlsx?from=' . e($from) . '&to=' . e($to)) ?>"><i class="bi bi-file-earmark-excel"></i> Excel</a><?php endif; ?></div></form>
<div class="row g-3 mb-3"><div class="col-lg-4"><div class="card-s h-100"><h2 class="h6">الإجمالي</h2><?php if (!$c['by_currency']): ?><div class="text-muted">لا تحصيل في الفترة.</div><?php endif; ?><?php foreach ($c['by_currency'] as $x): ?><div class="fs-5"><?= number_format((float)$x['total'], 2) ?> <small class="text-muted"><?= e($x['currency']) ?> (<?= (int)$x['n'] ?> دفعة)</small></div><?php endforeach; ?><?php if ($c['voided']): ?><div class="small text-danger mt-2"><?= (int)$c['voided'] ?> دفعة ملغاة (غير محتسبة)</div><?php endif; ?></div></div>
  <div class="col-lg-8"><div class="card-s h-100"><h2 class="h6">حسب طريقة الدفع</h2><?php if (!$c['by_method']): ?><div class="text-muted">—</div><?php else: ?><table class="table table-sm mb-0"><tbody><?php foreach ($c['by_method'] as $x): ?><tr><td><?= e($x['method']) ?></td><td><?= (int)$x['n'] ?></td><td class="text-end"><?= number_format((float)$x['total'], 2) ?> <?= e($x['currency']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></div></div>
<div class="card-s"><h2 class="h6">الدفعات (<?= count($c['rows']) ?>)</h2><?php if (!$c['rows']): ?><div class="empty-state">لا توجد دفعات.</div><?php else: ?><div class="table-responsive"><table class="table table-sm align-middle table-cards"><thead><tr><th>السند</th><th>التاريخ</th><th>الطالب</th><th>الطريقة</th><th>المرجع</th><th>المبلغ</th><th>الأمين</th></tr></thead><tbody>
<?php foreach ($c['rows'] as $x): ?><tr class="<?= $x['voided_at'] ? 'text-decoration-line-through text-muted' : '' ?>"><td data-label="السند"><a target="_blank" href="<?= url('school/fees/receipts/' . (int)$x['receipt_id'] . '/print') ?>"><?= e($x['receipt_no']) ?></a></td><td data-label="التاريخ" dir="ltr"><?= e($x['paid_on']) ?></td><td data-label="الطالب"><?= e($x['student']) ?></td><td data-label="الطريقة"><?= e($x['method']) ?></td><td data-label="المرجع"><?= e($x['reference_no']) ?></td><td data-label="المبلغ"><?= number_format((float)$x['amount'], 2) ?> <?= e($x['currency']) ?></td><td data-label="الأمين"><?= e($x['cashier']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
